        ScreenAnalysis: false,
        AnalysisPersonaPrompt: null,
        ProviderBaseUrl: null,
        ProviderModel: null,
        ProviderApiKeyRef: null,
        ProviderReasoningEffort: null,
        MinAnalysisIntervalSeconds: 5,
        Revision: 0);
}

