206	    [Guid("3628E81B-3CAC-4C60-B7F4-23CE0E0C3356")]
207	    [InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
208	    private interface IGraphicsCaptureItemInterop
209	    {
210	        [PreserveSig] int CreateForWindow(IntPtr window, ref Guid iid, out IntPtr value);

