 78	    private void OnFrameArrived(Direct3D11CaptureFramePool sender, object args)
 79	    {
 80	        try
 81	        {
 82	            using var frame = sender.TryGetNextFrame();
 83	            if (frame is null) return;
 84	            var bitmap = SoftwareBitmap.CreateCopyFromSurfaceAsync(frame.Surface).AsTask().GetAwaiter().GetResult();
 85	            lock (_gate)
 86	            {
 87	                _latest?.Dispose();
 88	                _latest = bitmap;
 89	                _hasFrame = true;
 90	            }
 91	        }
 92	        catch
 93	        {
 94	            // 单帧捕获失败忽略（下一帧再试）
 95	        }
 96	    }
 97	
 98	    private static byte[] ConvertToGrayThumbnail(SoftwareBitmap source)
 99	    {
100	        // BGRA8 → 320×180 灰度：CopyToBuffer 取紧凑像素（无 stride 填充），
101	        // 最近邻缩放 + 亮度权重（Rec.601）。
102	        var pixelCount = source.PixelWidth * source.PixelHeight;
103	        var buffer = new Windows.Storage.Streams.Buffer((uint)(pixelCount * 4));
104	        source.CopyToBuffer(buffer);
105	        var bytes = new byte[buffer.Length];
106	        using (var reader = Windows.Storage.Streams.DataReader.FromBuffer(buffer))
107	        {
108	            reader.ReadBytes(bytes);
109	        }
110	
111	        var gray = new byte[ThumbWidth * ThumbHeight];
112	        for (var y = 0; y < ThumbHeight; y++)
113	        {
114	            var srcY = y * source.PixelHeight / ThumbHeight;
115	            for (var x = 0; x < ThumbWidth; x++)
116	            {
117	                var srcX = x * source.PixelWidth / ThumbWidth;
118	                var p = (srcY * source.PixelWidth + srcX) * 4;
119	                var (b, g, r) = (bytes[p], bytes[p + 1], bytes[p + 2]);
120	                gray[y * ThumbWidth + x] = (byte)((r * 299 + g * 587 + b * 114) / 1000);
121	            }
122	        }
123	        return gray;
124	    }
125	
126	    private static readonly Guid IID_GraphicsCaptureItem = new("79C3F95B-31F7-4EC2-A464-632EF5D30760");
127	
128	    private static GraphicsCaptureItem CreateCaptureItemForMonitor(IntPtr hmon)
129	    {
130	        var factory = GetActivationFactory(typeof(GraphicsCaptureItem));
131	        var interop = (IGraphicsCaptureItemInterop)factory;
132	        var iid = IID_GraphicsCaptureItem; // 固定 IID（typeof().GUID 随投影版本漂移）
133	        var hr = interop.CreateForMonitor(hmon, ref iid, out var itemAbi);
134	        if (hr < 0) throw Marshal.GetExceptionForHR(hr)!;
135	        try
136	        {
137	            return GraphicsCaptureItem.FromAbi(itemAbi);
138	        }
139	        finally
140	        {
141	            Marshal.Release(itemAbi);
142	        }
143	    }
144	
145	    private static object GetActivationFactory(Type type)
146	    {
147	        // IActivationFactory IID（CsWinRT 投影中无此类型，用常量）
148	        var iid = new Guid("00000035-0000-0000-c000-000000000046");
149	        var hrCreate = WindowsCreateString(type.FullName!, (uint)type.FullName!.Length, out var hstring);
150	        if (hrCreate < 0) throw Marshal.GetExceptionForHR(hrCreate)!;
151	        try
152	        {
153	            var hr = RoGetActivationFactory(hstring, ref iid, out var factory);
154	            if (hr < 0) throw Marshal.GetExceptionForHR(hr)!;
155	            var obj = Marshal.GetObjectForIUnknown(factory); // RCW AddRef
156	            Marshal.Release(factory);                        // 平衡原始引用
157	            return obj;
158	        }
159	        finally
160	        {
161	            WindowsDeleteString(hstring);
162	        }
163	    }
164	
165	    private static IDirect3DDevice CreateD3DDevice()
166	    {
167	        var hr = D3D11CreateDevice(IntPtr.Zero, D3D_DRIVER_TYPE_HARDWARE, IntPtr.Zero,
168	            D3D11_CREATE_DEVICE_BGRA_SUPPORT, IntPtr.Zero, 0, D3D11_SDK_VERSION,
169	            out var d3dDevice, out _, out _);
170	        if (hr != 0)
171	        {
172	            // WARP 软件回退（虚拟机/无 GPU 环境）
173	            hr = D3D11CreateDevice(IntPtr.Zero, D3D_DRIVER_TYPE_WARP, IntPtr.Zero,
174	                D3D11_CREATE_DEVICE_BGRA_SUPPORT, IntPtr.Zero, 0, D3D11_SDK_VERSION,
175	                out d3dDevice, out _, out _);
176	            if (hr != 0) throw new InvalidOperationException($"D3D11CreateDevice 失败 hr=0x{hr:X8}");
177	        }
178	
179	        var iidDxgi = IID_IDXGIDevice;
180	        Marshal.QueryInterface(d3dDevice, ref iidDxgi, out var dxgiDevice);
181	        Marshal.Release(d3dDevice);
182	        try
183	        {
184	            hr = CreateDirect3D11DeviceFromDXGIDevice(dxgiDevice, out var graphicsDevice);
185	            if (hr < 0) throw new InvalidOperationException($"CreateDirect3D11DeviceFromDXGIDevice 失败 hr=0x{hr:X8}");
186	            return WinRT.MarshalInterface<IDirect3DDevice>.FromAbi(graphicsDevice);
187	        }
188	        finally
189	        {
190	            Marshal.Release(dxgiDevice);
191	        }
192	    }
193	
194	    public void Dispose()
195	    {
196	        if (_disposed) return;
197	        _disposed = true;
198	        _session?.Dispose();
199	        if (_framePool is not null) _framePool.FrameArrived -= OnFrameArrived;
200	        _framePool?.Dispose();
201	        _device?.Dispose();
202	        lock (_gate) _latest?.Dispose();
203	    }
