12	public sealed class SwitchableScreenCaptureSource : IScreenCaptureSource, IActivatableScreenCaptureSource, IDisposable
13	{
14	    private readonly Func<IScreenCaptureSource> _factory;
15	    private readonly SemaphoreSlim _gate = new(1, 1);
16	    private IScreenCaptureSource? _activeSource;
17	    private bool _enabled;
18	    private bool _disposed;
19	
20	    public SwitchableScreenCaptureSource(Func<IScreenCaptureSource> factory)
21	    {
22	        _factory = factory ?? throw new ArgumentNullException(nameof(factory));
23	    }
24	
25	    public void SetEnabled(bool enabled)
26	    {
27	        IScreenCaptureSource? sourceToDispose = null;
28	        _gate.Wait();
29	        try
30	        {
31	            if (_disposed || _enabled == enabled) return;
32	
33	            _enabled = enabled;
34	            if (!enabled)
35	            {
36	                sourceToDispose = _activeSource;
37	                _activeSource = null;
38	            }
39	        }
40	        finally
41	        {
42	            _gate.Release();
43	        }
44	
45	        DisposeSource(sourceToDispose);
46	    }
47	
