49	    {
50	        await _gate.WaitAsync(ct).ConfigureAwait(false);
51	        try
52	        {
53	            if (_disposed || !_enabled) return null;
54	
55	            _activeSource ??= _factory()
56	                ?? throw new InvalidOperationException("The screen capture factory returned null.");
57	            return await _activeSource.CaptureAsync(ct).ConfigureAwait(false);
58	        }
59	        finally
60	        {
61	            _gate.Release();
62	        }
63	    }
64	
65	    public void Dispose()
66	    {
67	        IScreenCaptureSource? sourceToDispose = null;
68	        _gate.Wait();
69	        try
70	        {
71	            if (_disposed) return;
72	
73	            _disposed = true;
74	            _enabled = false;
75	            sourceToDispose = _activeSource;
76	            _activeSource = null;
77	        }
78	        finally
79	        {
80	            _gate.Release();
81	        }
82	
83	        DisposeSource(sourceToDispose);
84	    }
85	
86	    private static void DisposeSource(IScreenCaptureSource? source)
87	    {
88	        if (source is IDisposable disposable) disposable.Dispose();
89	    }
90	}

