 14	public sealed class AnalysisEngine
 15	{
 16	    private readonly IScreenCaptureSource _capture;
 17	    private readonly IModelProvider? _model;
 18	    private readonly Func<AgentConfig> _config;
 19	    private readonly TimeSpan _captureInterval;
 20	    private readonly TimeSpan _analysisTimeout;
 21	    private readonly ChangeDetector _detector = new();
 22	    private ulong? _previousHash;
 23	    private AnalysisThrottle _throttle;
 24	
 25	    public event Action<ScreenEvent>? EventRaised;
 26	
 27	    public AnalysisEngine(
 28	        IScreenCaptureSource capture,
 29	        IModelProvider? model,
 30	        Func<AgentConfig> config,
 31	        TimeSpan? captureInterval = null,
 32	        TimeSpan? analysisTimeout = null)
 33	    {
 34	        _capture = capture ?? throw new ArgumentNullException(nameof(capture));
 35	        _model = model;
 36	        _config = config ?? throw new ArgumentNullException(nameof(config));
 37	        _captureInterval = captureInterval ?? TimeSpan.FromSeconds(1);
 38	        _analysisTimeout = analysisTimeout ?? TimeSpan.FromSeconds(30);
 39	        if (_analysisTimeout <= TimeSpan.Zero && _analysisTimeout != Timeout.InfiniteTimeSpan)
 40	            throw new ArgumentOutOfRangeException(nameof(analysisTimeout));
 41	        _throttle = new AnalysisThrottle(TimeSpan.FromSeconds(config().MinAnalysisIntervalSeconds));
 42	    }
 43	
 44	    /// <summary>单步：捕获一帧并判断是否需要分析。返回事件或 null。</summary>
 45	    public async Task<ScreenEvent?> TickAsync(DateTime now, CancellationToken ct)
 46	    {
 47	        var cfg = _config();
 48	        if (!cfg.ScreenAnalysis) return null; // 静默：不截屏不分析
 49	
 50	        var frame = await _capture.CaptureAsync(ct).ConfigureAwait(false);
 51	        if (frame is null) return null;
 52	
 53	        var hash = FrameHasher.HashGrayscale(frame.Gray, frame.Width, frame.Height);
 54	        if (_previousHash is null)
 55	        {
 56	            _previousHash = hash; // 首帧只建立基准，不触发分析
 57	            return null;
 58	        }
 59	        var changed = _detector.HasChanged(_previousHash.Value, hash);
 60	        _previousHash = hash;
 61	
 62	        if (!changed) return null;
 63	        SyncThrottle(cfg);
 64	        if (!_throttle.TryTake(now)) return null;
 65	
 66	        return await AnalyzeAsync(frame, hash, cfg, ct).ConfigureAwait(false);
 67	    }
 68	
 69	    /// <summary>循环宿主：Tick + 捕获间隔；ct 取消退出。</summary>
 70	    public async Task RunAsync(CancellationToken ct)
 71	    {
 72	        while (!ct.IsCancellationRequested)
 73	        {
 74	            try
 75	            {
 76	                var evt = await TickAsync(DateTime.Now, ct).ConfigureAwait(false);
 77	                if (evt is not null) EventRaised?.Invoke(evt);
 78	            }
 79	            catch (OperationCanceledException) when (ct.IsCancellationRequested)
 80	            {
 81	                break;
 82	            }
 83	            catch (Exception)
 84	            {
 85	                // 单帧分析失败不拖垮循环（下一拍重试）；错误已由 AnalyzeAsync 降级处理
 86	            }
 87	            try
 88	            {
 89	                await Task.Delay(_captureInterval, ct).ConfigureAwait(false);
 90	            }
 91	            catch (OperationCanceledException) when (ct.IsCancellationRequested)
 92	            {
 93	                break;
 94	            }
 95	        }
 96	    }
 97	
 98	    /// <summary>评论文本 → 屏幕事件分类（关键词粗分类，可单测）。</summary>
 99	    public static ScreenEventKind Classify(string text)
100	    {
101	        if (text.Contains("代码") || text.Contains("写码") || text.Contains("编程")
102	            || text.Contains("开发") || text.Contains("bug") || text.Contains("Bug"))
103	            return ScreenEventKind.Coding;
104	        if (text.Contains("视频") || text.Contains("电影") || text.Contains("追剧")
105	            || text.Contains("直播") || text.Contains("看剧"))
106	            return ScreenEventKind.Video;
107	        if (text.Contains("游戏") || text.Contains("打游戏") || text.Contains("对战")
108	            || text.Contains("副本"))
109	            return ScreenEventKind.Gaming;
110	        if (text.Contains("浏览") || text.Contains("网页") || text.Contains("浏览器")
111	            || text.Contains("购物") || text.Contains("刷"))
112	            return ScreenEventKind.Browsing;
113	        if (text.Contains("离开") || text.Contains("空闲") || text.Contains("休息")
114	            || text.Contains("不在"))
115	            return ScreenEventKind.Idle;
116	        return ScreenEventKind.AppSwitch;
117	    }
118	
119	    private async Task<ScreenEvent> AnalyzeAsync(
120	        CapturedFrame frame, ulong hash, AgentConfig cfg, CancellationToken ct)
121	    {
122	        if (_model is null)
123	        {
124	            return new ScreenEvent(DateTime.Now, ScreenEventKind.Unknown, "", hash);
125	        }
126	
127	        try
128	        {
129	            var prompt = string.IsNullOrWhiteSpace(cfg.AnalysisPersonaPrompt)
130	                ? PersonaEngine.BasePrompt
131	                : cfg.AnalysisPersonaPrompt;
132	            var request = new ChatRequest(
133	                SystemPrompt: prompt,
134	                Messages:
135	                [
136	                    new ChatMessage(ChatRole.User,
137	                        "这是当前屏幕的截图。用一句话简短评论用户在做什么（30 字内，口语化，按你的人格）",
138	                        ImageDataUrl: frame.ToDataUrl()),
139	                ],
140	                Temperature: PersonaEngine.Temperature,
141	                MaxTokens: PersonaEngine.MaxTokens);
142	
143	            using var deadline = CreateAnalysisDeadline(ct);
144	            var requestCt = deadline?.Token ?? ct;
145	            var operation = _model.CompleteAsync(request, requestCt);
146	            try
147	            {
148	                var result = await operation.WaitAsync(requestCt).ConfigureAwait(false);
149	                return new ScreenEvent(DateTime.Now, Classify(result.Text), result.Text, hash);
150	            }
151	            finally
152	            {
153	                if (requestCt.IsCancellationRequested)
154	                    ObserveDetachedTask(operation);
155	            }
156	        }
157	        catch (OperationCanceledException) when (ct.IsCancellationRequested)
158	        {
159	            throw;
160	        }
161	        catch (Exception)
162	        {
163	            // 分析 deadline 或模型失败显式降级为纯变化事件（限频已挡频次；UI 有默认台词）
164	            return new ScreenEvent(DateTime.Now, ScreenEventKind.Unknown, "", hash);
165	        }
166	    }
167	
168	    private static void ObserveDetachedTask(Task task)
169	    {
170	        _ = task.ContinueWith(
171	            static completed => _ = completed.Exception,
172	            CancellationToken.None,
173	            TaskContinuationOptions.OnlyOnFaulted | TaskContinuationOptions.ExecuteSynchronously,
174	            TaskScheduler.Default);
175	    }
176	
177	    private CancellationTokenSource? CreateAnalysisDeadline(CancellationToken ct)
178	    {
179	        if (_analysisTimeout == Timeout.InfiniteTimeSpan) return null;
180	        var deadline = CancellationTokenSource.CreateLinkedTokenSource(ct);
181	        deadline.CancelAfter(_analysisTimeout);
182	        return deadline;
183	    }
184	
185	    private void SyncThrottle(AgentConfig cfg)
186	    {
187	        var interval = TimeSpan.FromSeconds(Math.Max(0, cfg.MinAnalysisIntervalSeconds));
188	        if (interval != _throttle.Interval)
189	        {
190	            _throttle = new AnalysisThrottle(interval);
191	        }
192	    }
193	}

