134	                Messages:
135	                [
136	                    new ChatMessage(ChatRole.User,
137	                        "这是当前屏幕的截图。用一句话简短评论用户在做什么（30 字内，口语化，按你的人格）",
138	                        ImageDataUrl: frame.ToDataUrl()),
139	                ],
140	                Temperature: PersonaEngine.Temperature,
141	                MaxTokens: PersonaEngine.MaxTokens);
142	
143	            using var deadline = CreateAnalysisDeadline(ct);
144	            var requestCt = deadline?.Token ?? ct;
145	            var operation = _model.CompleteAsync(request, requestCt);
146	            try
147	            {
148	                var result = await operation.WaitAsync(requestCt).ConfigureAwait(false);
149	                return new ScreenEvent(DateTime.Now, Classify(result.Text), result.Text, hash);
150	            }
151	            finally
152	            {
153	                if (requestCt.IsCancellationRequested)
154	                    ObserveDetachedTask(operation);
155	            }
156	        }
157	        catch (OperationCanceledException) when (ct.IsCancellationRequested)
158	        {
159	            throw;
160	        }
161	        catch (Exception)
162	        {
163	            // 分析 deadline 或模型失败显式降级为纯变化事件（限频已挡频次；UI 有默认台词）
164	            return new ScreenEvent(DateTime.Now, ScreenEventKind.Unknown, "", hash);
165	        }
166	    }
167	
168	    private static void ObserveDetachedTask(Task task)
169	    {
170	        _ = task.ContinueWith(
171	            static completed => _ = completed.Exception,
172	            CancellationToken.None,
173	            TaskContinuationOptions.OnlyOnFaulted | TaskContinuationOptions.ExecuteSynchronously,
174	            TaskScheduler.Default);
175	    }
176	
177	    private CancellationTokenSource? CreateAnalysisDeadline(CancellationToken ct)
178	    {
179	        if (_analysisTimeout == Timeout.InfiniteTimeSpan) return null;
180	        var deadline = CancellationTokenSource.CreateLinkedTokenSource(ct);
181	        deadline.CancelAfter(_analysisTimeout);
182	        return deadline;
183	    }
184	
185	    private void SyncThrottle(AgentConfig cfg)
186	    {
187	        var interval = TimeSpan.FromSeconds(Math.Max(0, cfg.MinAnalysisIntervalSeconds));
188	        if (interval != _throttle.Interval)
189	        {
190	            _throttle = new AnalysisThrottle(interval);
191	        }
192	    }
193	}

